package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import com.google.android.gms.tasks.Tasks;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class ChapterLanguageRegressionTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long until=SystemClock.elapsedRealtime()+40000;while(SystemClock.elapsedRealtime()<until){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(predicate.getAsBoolean()));if(ready.get())return;Thread.sleep(40);}throw new AssertionError(message);}
    void drag(MainActivity a,float fraction,boolean advance){long now=SystemClock.uptimeMillis();float y=a.seek.getHeight()/2f;float start=a.seek.getPaddingLeft()+8;float end=a.seek.getPaddingLeft()+fraction*(a.seek.getWidth()-a.seek.getPaddingLeft()-a.seek.getPaddingRight());MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,start,y,0);a.seek.dispatchTouchEvent(down);down.recycle();if(advance){check(a.seeking,"seek capture missing");a.position=a.chapters.get(2).start;a.showPosition(true);}MotionEvent move=MotionEvent.obtain(now,now+40,MotionEvent.ACTION_MOVE,end,y,0);a.seek.dispatchTouchEvent(move);move.recycle();MotionEvent up=MotionEvent.obtain(now,now+80,MotionEvent.ACTION_UP,end,y,0);a.seek.dispatchTouchEvent(up);up.recycle();}
    void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(300);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();MainActivity activity=null;OfflineTranslation translation=null;boolean passed=false;try{
        check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for regression");activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","chapter_language_qa").putExtra("book_name","章节进度验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system.initialized&&a.offlineReady,"voices not ready");ui(()->{StringBuilder text=new StringBuilder();for(int c=1;c<=3;c++){text.append("第").append(c).append("章 测试章节\n");for(int n=0;n<80;n++)text.append("山间吹来了微风，书页轻轻翻动。我们沿着小路继续向前，欣赏四周的风景。\n");}a.text=text.toString();a.chapters=MainActivity.parse(a.text);check(a.chapters.size()==3,"fixture chapter count");a.position=a.chapters.get(1).start;a.showPosition(true);check(a.chapter==1&&a.seek.getProgress()==0,"chapter 2 starts at nonzero slider");MainActivity.Chapter c=a.chapters.get(1);a.position=ChapterProgress.position(.5f,c.start,c.end);a.showPosition(true);check(Math.abs(a.seek.getProgress()-500)<=1,"chapter midpoint not half");check(a.progress.getText().toString().contains("50.0"),"chapter percentage wrong");check(Math.abs(a.mediaState().fraction-.5f)<.001,"lock-screen progress differs");});screenshot("chapter-progress-middle.png");ui(()->{drag(a,.75f,false);check(a.chapter==1,"drag left current chapter");float progress=a.mediaState().fraction;check(progress>.60&&progress<.85,"drag is book-relative: "+progress);a.seekChapter(1,0);check(a.position==a.chapters.get(1).start&&a.seek.getProgress()==0,"chapter seek to start");drag(a,.6f,true);check(a.chapter==1,"drag changed target chapter when playback advanced");a.seekChapter(1,1);check(a.position>=a.chapters.get(1).start&&a.position<a.chapters.get(1).end,"100% drag crossed chapter");a.mediaJump(1);check(a.chapter==2&&a.seek.getProgress()==0,"next chapter not reset");a.readingLanguage="ja";a.systemVoiceKey="";a.chooseVoice();check(!a.voicePicker.host.items().isEmpty(),"Japanese voices unavailable");check(a.voicePicker.tab==1&&!a.voicePicker.previewButtons.isEmpty(),"Japanese chooser defaulted to empty built-in tab");a.voicePicker.dismiss();});
        translation=new OfflineTranslation(context);Tasks.await(translation.available(),30,TimeUnit.SECONDS);String[] snippets={"嗯。","唔。","哼！","哈！","第一章","夜幕低垂，群山间的雷鸣终于渐渐平息。"};StringBuilder raw=new StringBuilder();for(String input:snippets){String guess=Tasks.await(translation.identifier.identifyLanguage(input),15,TimeUnit.SECONDS);raw.append(input).append('=').append(guess).append(';');for(String target:Arrays.asList("zh","en","ja")){OfflineTranslation.Session session=translation.session(Collections.singletonList(input),target);for(OfflineTranslation.Unit unit:session.plan(0))check(unit.source.equals("zh"),"Chinese snippet misidentified: "+unit.source);check(session.missingUpcoming(1000).isEmpty(),"false missing models for "+input);}}result.putString("rawModelGuesses",raw.toString());
        String[] codes={"zh","ja","ko","en","fr","de","es","pt","ru","ar","hi","id","vi","th"};String[] samples={"今天阳光明媚，我们一起到公园散步。这里有很多美丽的花朵。","今日はいい天気です。私たちは公園を歩いて、美しい花を見ています。","오늘은 날씨가 좋습니다. 우리는 공원에서 산책하며 아름다운 꽃을 보고 있습니다.","The weather is beautiful today. We are walking in the park and looking at the flowers.","Il fait beau aujourd’hui. Nous nous promenons dans le parc et regardons les belles fleurs.","Heute ist das Wetter schön. Wir gehen im Park spazieren und schauen uns die schönen Blumen an.","Hoy hace buen tiempo. Estamos paseando por el parque y mirando las hermosas flores.","Hoje o tempo está bom. Estamos caminhando pelo parque e olhando as belas flores.","Сегодня хорошая погода. Мы гуляем в парке и любуемся красивыми цветами.","الطقس جميل اليوم. نحن نمشي في الحديقة ونشاهد الزهور الجميلة.","आज मौसम बहुत अच्छा है। हम पार्क में घूम रहे हैं और सुंदर फूल देख रहे हैं।","Cuaca hari ini sangat cerah. Kami berjalan di taman dan melihat bunga yang indah.","Hôm nay thời tiết rất đẹp. Chúng tôi đi dạo trong công viên và ngắm những bông hoa xinh đẹp.","วันนี้อากาศดีมาก พวกเรากำลังเดินเล่นในสวนสาธารณะและชมดอกไม้ที่สวยงาม"};for(int i=0;i<codes.length;i++){OfflineTranslation.Session session=translation.session(Collections.singletonList(samples[i]),"zh");for(OfflineTranslation.Unit unit:session.plan(0))check(unit.source.equals(codes[i]),"language "+codes[i]+" identified as "+unit.source);}
        String id="f0425c54-6a4a-4312-987e-12535d6dfbc4";File book=new File(context.getFilesDir(),"book_"+id+".txt");if(book.exists()){String original;try(InputStream in=new FileInputStream(book)){original=new String(MainActivity.readBytes(in),StandardCharsets.UTF_8);}int position=context.getSharedPreferences("reader_"+id,0).getInt("position",0);List<String> chunks=new ArrayList<>();List<Integer> offsets=new ArrayList<>();for(int at=Math.min(Math.max(0,position),original.length()-1),length=0;at<original.length()&&length<16000;){int end=TranslationText.end(original,at,original.length());if(TranslationText.speakable(original.substring(at,end))){chunks.add(original.substring(at,end));offsets.add(at);}length+=end-at;at=end;}OfflineTranslation.Session novel=translation.session(chunks,"ja",original,offsets);check(novel.missingUpcoming(16000).isEmpty(),"novel current reading position falsely requires models");result.putInt("novelSegmentsChecked",chunks.size());}
        result.putString("result","PASS: chapter-relative UI progress, real slider gestures, chapter-local seek endpoints, capture chapter during drag, next-chapter reset, lock-screen fraction; Japanese voice list tab; Chinese short snippets cannot request Burmese for zh/en/ja; all 15 source variants; current novel preflight");passed=true;
    }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}if(translation!=null)translation.close();context.getSharedPreferences("reader_chapter_language_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_chapter_language_qa.txt.position").delete();}finish(passed?-1:0,result);}
}
